import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { APP_INTERCEPTOR } from '@nestjs/core';
import { Observable } from 'rxjs';
import { map, tap } from 'rxjs/operators';

/**
 * Per-request timing slot. Starts null; ExecutionTimer is supposed to
 * populate it on the way out, and ResponseTransform reads it when it
 * builds the response envelope.
 */
interface RequestMeta {
  executionMs: number | null;
}

/**
 * WRITER: measures how long the handler took and stores it on the
 * request so a later interceptor can read it.
 */
@Injectable()
export class ExecutionTimer implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    request.meta = (request.meta as RequestMeta) ?? { executionMs: null };

    const start = Date.now();

    return next.handle().pipe(
      tap(() => {
        // Outbound leg: write the measured duration.
        (request.meta as RequestMeta).executionMs = Date.now() - start;
      }),
    );
  }
}

/**
 * READER: wraps the handler's return value into the response envelope,
 * reading whatever ExecutionTimer left on the request.
 */
@Injectable()
export class ResponseTransform implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();

    return next.handle().pipe(
      map((data) => ({
        data,
        meta: {
          executionMs: (request.meta as RequestMeta | undefined)?.executionMs ?? null,
        },
      })),
    );
  }
}

/**
 * Global interceptor registration — order matters because interceptors
 * nest onion-style around the handler.
 */
export const GLOBAL_INTERCEPTORS = [
  { provide: APP_INTERCEPTOR, useClass: ExecutionTimer },
  { provide: APP_INTERCEPTOR, useClass: ResponseTransform },
];
